<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { PlanCreateInput, PlanSummary } from '@cyberboard/types'
import StatusBadge from '@cyberboard/ui/components/StatusBadge.vue'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { adminApi, getApiErrorMessage, normalizePage } from '../api'
const loading=ref(true); const saving=ref(false); const error=ref(''); const formError=ref(''); const showForm=ref(false); const editingId=ref<string|null>(null); const plans=ref<PlanSummary[]>([]); const page=ref(1); const pageSize=20; const total=ref(0)
const form=reactive<PlanCreateInput>({name:'',description:'',priceCents:0,currency:'CNY',durationDays:30,quotaBytes:200000000000,deviceLimit:3,nodeGroupIds:[],status:'draft'})
function resetForm(){Object.assign(form,{name:'',description:'',priceCents:0,currency:'CNY',durationDays:30,quotaBytes:200000000000,deviceLimit:3,nodeGroupIds:[],status:'draft'});editingId.value=null;showForm.value=false;formError.value=''}
function edit(plan:PlanSummary){Object.assign(form,{name:plan.name,description:plan.description,priceCents:plan.priceCents,currency:plan.currency,durationDays:plan.durationDays,quotaBytes:plan.quotaBytes,deviceLimit:plan.deviceLimit,nodeGroupIds:plan.nodeGroupIds,status:plan.status});editingId.value=plan.id;showForm.value=true}
async function load(){loading.value=true;error.value='';try{const result=normalizePage(await adminApi.listPlans({page:page.value,pageSize}),page.value,pageSize);plans.value=result.items;total.value=result.total}catch(cause){plans.value=[];total.value=0;error.value=getApiErrorMessage(cause)}finally{loading.value=false}}
async function save(){saving.value=true;formError.value='';try{if(editingId.value)await adminApi.updatePlan(editingId.value,form);else await adminApi.createPlan(form);resetForm();await load()}catch(cause){formError.value=getApiErrorMessage(cause)}finally{saving.value=false}}
async function toggleStatus(plan:PlanSummary){try{await adminApi.updatePlan(plan.id,{status:plan.status==='active'?'archived':'active'});await load()}catch(cause){error.value=getApiErrorMessage(cause)}}
onMounted(load)
</script>
<template><div class="page-heading"><div><p class="eyebrow">商业与权益</p><h1>套餐</h1><p>管理价格、额度、有效期和设备限制。</p></div><button class="primary-button" type="button" @click="showForm=true;editingId=null">+ 创建套餐</button></div><section v-if="showForm" class="panel form-panel"><div class="panel-heading"><div><h2>{{editingId?'编辑套餐':'创建套餐'}}</h2><p>价格以最小货币单位提交，额度以字节提交。</p></div><button class="button button--secondary" type="button" @click="resetForm">取消</button></div><form class="resource-form" @submit.prevent="save"><label>名称<input v-model="form.name" required :disabled="saving" /></label><label>描述<input v-model="form.description" :disabled="saving" /></label><label>价格（分）<input v-model.number="form.priceCents" type="number" min="0" required :disabled="saving" /></label><label>币种<input v-model="form.currency" required :disabled="saving" /></label><label>有效期（天）<input v-model.number="form.durationDays" type="number" min="1" required :disabled="saving" /></label><label>流量额度（字节）<input v-model.number="form.quotaBytes" type="number" min="0" required :disabled="saving" /></label><label>设备数<input v-model.number="form.deviceLimit" type="number" min="1" required :disabled="saving" /></label><label>状态<select v-model="form.status" :disabled="saving"><option value="draft">草稿</option><option value="active">生效</option><option value="archived">归档</option></select></label><p v-if="formError" class="form-error" role="alert">{{formError}}</p><button class="primary-button" type="submit" :disabled="saving">{{saving?'保存中…':'保存套餐'}}</button></form></section><section class="panel"><StatePanel v-if="loading" title="正在加载套餐" description="正在读取套餐配置。"/><StatePanel v-else-if="error" title="套餐加载失败" :description="error" action-label="重试" @action="load"/><StatePanel v-else-if="!plans.length" title="暂无套餐" description="控制面尚未创建套餐。" action-label="刷新" @action="load"/><div v-else class="table-wrap"><table><thead><tr><th>套餐</th><th>价格</th><th>有效期</th><th>流量</th><th>设备</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="plan in plans" :key="plan.id"><td><strong>{{plan.name}}</strong><small>{{plan.description}}</small></td><td>{{(plan.priceCents/100).toFixed(2)}} {{plan.currency}}</td><td>{{plan.durationDays}} 天</td><td class="mono">{{(plan.quotaBytes/1e9).toFixed(0)}} GB</td><td>{{plan.deviceLimit}}</td><td><StatusBadge :status="plan.status"/></td><td><button class="row-action" type="button" @click="edit(plan)">编辑</button><button class="row-action" type="button" @click="toggleStatus(plan)">{{plan.status==='active'?'归档':'生效'}}</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>第 {{page}} 页 · 共 {{total}} 条</span><button class="button button--secondary" :disabled="page*pageSize>=total||loading" @click="page++;load()">下一页</button></div></div></section></template>
